// src/components/NewDeploymentButton.js
import React from 'react';
import { useNavigate } from 'react-router-dom';

const NewDeploymentButton = () => {
  const navigate = useNavigate();

  const handleClick = () => {
    navigate('/deployments/new');
  };

  return (
    <div>
      <h1>Deployments</h1>
      <button onClick={handleClick}>New Deployment</button>
    </div>
  );
};

export default NewDeploymentButton;
